"""Documented REST endpoint catalog (generated by tools/build_endpoint_catalog.py)."""
from __future__ import annotations

import json
import re
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

from ..version.release import Release

DATA = Path(__file__).resolve().parent / "data"


def norm_path(path: str) -> str:
    """'/projects/{projectId}/workitems' -> '/projects/{}/workitems' (parameter names ignored)."""
    path = path.split("?", 1)[0]
    if path.startswith("/polarion/rest/v1"):
        path = path[len("/polarion/rest/v1"):]
    return re.sub(r"\{[^}]+\}", "{}", path.rstrip("/") or "/")


def endpoint_key(spec: str) -> tuple[str, str]:
    """'GET /projects/{projectId}' -> ('GET', '/projects/{}')."""
    method, path = spec.split(None, 1)
    return method.upper(), norm_path(path.strip())


@dataclass(frozen=True)
class Operation:
    method: str
    path: str
    tag: str
    summary: str
    since: Release | None        # None = older than the oldest logged release
    removed_in: Release | None

    @property
    def key(self) -> tuple[str, str]:
        return self.method, norm_path(self.path)

    def exists_in(self, release: Release) -> bool:
        if self.since is not None and release < self.since:
            return False
        if self.removed_in is not None and release >= self.removed_in:
            return False
        return True


class EndpointCatalog:
    def __init__(self, data: dict) -> None:
        self.generated = data.get("generated")
        self.releases = [Release.parse(r) for r in data.get("releases", [])]
        self.oldest_logged = Release.try_parse(data.get("oldest_logged_release"))
        self.newest = max(self.releases) if self.releases else None
        self._ops: dict[tuple[str, str], Operation] = {}
        for o in data.get("operations", []):
            op = Operation(o["method"], o["path"], o.get("tag", ""), o.get("summary", ""),
                           Release.try_parse(o.get("since")), Release.try_parse(o.get("removed_in")))
            self._ops[op.key] = op

    @classmethod
    @lru_cache(maxsize=1)
    def load(cls) -> "EndpointCatalog":
        return cls(json.loads((DATA / "endpoint_catalog.json").read_text(encoding="utf-8")))

    def __len__(self) -> int:
        return len(self._ops)

    def operations(self) -> list[Operation]:
        return list(self._ops.values())

    def get(self, spec: str) -> Operation | None:
        return self._ops.get(endpoint_key(spec))

    def exists(self, spec: str, release: Release | None) -> bool | None:
        """True/False if documented for that release; None if the endpoint or release is unknown."""
        op = self.get(spec)
        if op is None or release is None:
            return None
        if op.since is None and self.oldest_logged and release < self.oldest_logged:
            return None    # the log can't tell how old an un-dated endpoint is
        return op.exists_in(release)

    def operations_for(self, release: Release) -> list[Operation]:
        return [o for o in self._ops.values() if o.exists_in(release)]

    def min_release_for(self, present: set[tuple[str, str]]) -> Release | None:
        """Lowest release consistent with a live endpoint set (fingerprinting)."""
        dated = [op.since for key, op in self._ops.items() if key in present and op.since]
        return max(dated) if dated else None
